package app.hookline.radar.core.radar

import app.hookline.radar.core.hdf5.Hdf5File
import app.hookline.radar.core.odim.CompositeTile
import app.hookline.radar.core.odim.Odim
import app.hookline.radar.core.odim.Projection
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test
import kotlin.math.abs

/**
 * Fixtures are generated by tools/odim-fixtures/make_fixtures.py with h5py;
 * values follow formulas documented there. The HDF5 reader was also checked
 * byte-for-byte against h5py on real Belgian, Dutch and Australian ODIM files.
 */
class OdimTest {
    private fun fixture(name: String): ByteArray =
        javaClass.getResourceAsStream("/odim/$name")!!.use { it.readBytes() }

    @Test
    fun readsOldStyleScanWithInheritanceAndSentinels() {
        val f = Odim.read(fixture("deess_scan_0.5_DBZH.h5"))
        assertEquals("SCAN", f.`object`)
        assertEquals("deess", f.node())
        assertEquals(51.4055, f.lat, 1e-9)
        val s = f.scans.single()
        assertEquals(0.5, s.elevationDeg, 1e-9)
        assertEquals(360, s.nrays)
        assertEquals(120, s.nbins)
        assertEquals(1000.0, s.binSpacingM, 1e-9)
        assertEquals(500.0, s.firstBinCenterM(), 1e-9)
        val dbzh = s.fields.getValue("DBZH")
        // raw (10 + 20) % 200 + 1 = 31 -> 31 * 0.5 - 32
        assertEquals(-16.5f, dbzh.value(10, 20), 1e-6f)
        assertEquals(Odim.UNDETECT, dbzh.value(0, 0))
        assertTrue(dbzh.value(0, 1).isNaN())
        // ray centres from how/startazA and stopazA
        assertEquals(0.5f, s.azimuths[0], 1e-6f)
        assertEquals(359.5f, s.azimuths[359], 1e-6f)
        // 06:15:00 UTC on 7 Oct 2026
        assertEquals(1791353700000L, s.startMillis)
        assertEquals(1791353745000L, s.endMillis)
    }

    @Test
    fun readsNewStyleFileWithDenseStorage() {
        val bytes = fixture("deess_scan_0.5_VRADH_v114.h5")
        assertTrue(Hdf5File.isHdf5(bytes))
        val s = Odim.read(bytes).scans.single()
        // raw 128 + (10 % 50) - 25 = 113 -> 113 * 0.5 - 64
        assertEquals(-7.5f, s.fields.getValue("VRADH").value(10, 20), 1e-6f)
    }

    @Test
    fun adaptsScanToSweepUsableByTheRenderer() {
        val f = Odim.read(fixture("deess_scan_0.5_DBZH.h5"))
        val site = SiteLocation(f.lat.toFloat(), f.lon.toFloat(), f.heightM.toInt())
        val sweep = OdimAdapter.toSweep(f.scans.single(), "deess", 5, site)!!
        assertEquals(360, sweep.radials.size)
        assertTrue(sweep.has(Moment.REFLECTIVITY))
        val md = sweep.radials[10].moments.getValue(Moment.REFLECTIVITY)
        assertEquals(500, md.firstGateMeters)
        assertEquals(1000, md.gateSpacingMeters)
        assertEquals(-16.5f, md.gates[20], 1e-6f)
        assertEquals(Gate.BELOW_THRESHOLD, sweep.radials[0].moments.getValue(Moment.REFLECTIVITY).gates[0])

        val tex = SweepTexture.from(sweep, Moment.REFLECTIVITY)!!
        assertEquals(360, tex.radialCount)
        // 20.5 km out along the ray centred at 10.5 deg (gate 20)
        assertEquals(-16.5f, tex.valueAtPolar(10.5, 20_500.0)!!, 1e-6f)
        assertEquals(0.5f, OdimAdapter.tiltKey(0.4999))
        assertEquals(Moment.VELOCITY, OdimAdapter.momentFor("vradh"))
        assertNull(OdimAdapter.momentFor("KDP"))
    }

    @Test
    fun projectionMatchesProjForOperaLaea() {
        // Reference values from PROJ 9 (pyproj) for the OPERA composite definition.
        val p = Projection.parse("+proj=laea +lat_0=55.0 +lon_0=10.0 +x_0=1950000.0 +y_0=-2100000.0 +units=m +ellps=WGS84")
        val origin = p.forward(55.0, 10.0)
        assertEquals(1_950_000.0, origin[0], 1e-6)
        assertEquals(-2_100_000.0, origin[1], 1e-6)
        val athens = p.forward(37.9838, 23.7275)
        // pyproj: dx = 1211407.103, dy = -1771988.617 from the false origin
        assertEquals(1_211_407.103, athens[0] - 1_950_000.0, 0.01)
        assertEquals(-1_771_988.617, athens[1] + 2_100_000.0, 0.01)
    }

    @Test
    fun compositeCornersLandOnTheGridEdgesAndTilesSample() {
        val grid = Odim.read(fixture("opera_comp_laea.h5")).grid!!
        assertEquals(380, grid.xsize)
        assertEquals(440, grid.ysize)
        val loc = CompositeTile.Locator(grid)
        val c = grid.corners
        val ll = loc.colRow(c[5], c[4])
        val ur = loc.colRow(c[3], c[2])
        assertEquals(0.0, ll[0], 1e-6); assertEquals(440.0, ll[1], 1e-6)
        assertEquals(380.0, ur[0], 1e-6); assertEquals(0.0, ur[1], 1e-6)

        // Greece is inside the composite.
        val v = CompositeTile.valueAt(grid, loc, 37.98, 23.73)
        assertTrue(!v.isNaN())

        val tile = CompositeTile.build(grid, loc, 34.0, 19.0, 42.0, 29.0, 2048, 38.0, 23.0, true)
        assertNotNull(tile)
        tile!!
        assertEquals(tile.texWidth * tile.texHeight, tile.values.size)
        assertEquals(64 * 64 * 6 * 4, tile.mesh.size)
        // A tile far outside Europe doesn't exist.
        assertNull(CompositeTile.build(grid, loc, -40.0, 140.0, -30.0, 150.0, 2048, 0.0, 0.0, true))

        val small = CompositeTile.build(grid, loc, 30.0, -30.0, 72.0, 50.0, 100, 50.0, 10.0, true)!!
        assertTrue(small.step > 1)
        assertTrue(small.texWidth <= 100 && small.texHeight <= 100)
    }
}
